class Solution {
public:
    int maxProduct(vector<int>& nums) {
        int hi = nums[0], lo = nums[0], best = nums[0]; // 以当前位置结尾的最大积、最小积
        for (int i = 1; i < nums.size(); i++) {
            int x = nums[i];
            if (x < 0) {
                swap(hi, lo);                           // 乘负数，大小互换
            }
            hi = max(x, hi * x);
            lo = min(x, lo * x);
            best = max(best, hi);
        }
        return best;
    }
};

